update pages set contenu = '{"sections":[]}'::jsonb where path = '/offres/audit-conseil-maintenance/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Conseil en maintenance industrielle : sachez où part le budget","mecanisme":"Un référent technique passe du vrai temps sur votre site et croise la GMAO, les historiques, les contrats et les entretiens terrain. Il vous remet ensuite un plan d''actions chiffré et classé par gain attendu.","cta":"Demander mon diagnostic gratuit","telephone":"04 78 33 72 05","phraseDelai":", du lundi au vendredi de 8h00 à 18h30. Le premier état des lieux est gratuit"},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers, autant de sites déjà regardés de près"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, le référent qui audite votre site est passé par là"},{"valeur":"10","libelle":"hubs de techniciens, Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon, Nantes"}]},{"type":"probleme","punchline":"Quelque part, l''argent se perd. Personne ne sait où.","puces":[{"accroche":"Des habitudes jamais remises en question","texte":"et des prestataires reconduits sans remise en concurrence."},{"accroche":"Une GMAO sous-exploitée ou absente","texte":", des historiques trop pauvres pour décider."},{"accroche":"Un plan de préventif incomplet","texte":"et une équipe qui court derrière le correctif."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Diagnostic maintenance gratuit","texte":"questionnaire et échange technique, recommandation argumentée"},"benefice":"Vous savez si une étude approfondie se justifie, et à quoi elle servirait. Y compris quand la conclusion est que tout va bien"},{"prestation":{"accroche":"Audit de maintenance sur site","texte":"visite des installations, entretiens techniciens et encadrement, revue des historiques, de la GMAO, des contrats et des stocks"},"benefice":"L''évaluation croise ce que disent les données et ce que montre le terrain. Les deux racontent rarement la même histoire"},{"prestation":{"accroche":"Analyse de la stratégie par équipement","texte":"équilibre préventif, correctif assumé et surveillance conditionnelle, selon la criticité"},"benefice":"L''effort va là où l''arrêt fait le plus mal, et le préventif inutile s''arrête"},{"prestation":{"accroche":"Revue des données et des outils","texte":"qualité des historiques, indicateurs qui comptent, temps moyen entre pannes, disponibilité, coût par équipement"},"benefice":"Vous pilotez sur des chiffres, et non plus sur des impressions"},{"prestation":{"accroche":"Revue des pièces et des achats","texte":"stock de rechange, références critiques, délais fournisseurs, adéquation des contrats au besoin réel"},"benefice":"Le stock dormant se réduit, les références critiques se sécurisent"},{"prestation":{"accroche":"Plan d''actions chiffré et restitué en direction","texte":"forces, faiblesses, risques, priorités, gains rapides en tête"},"benefice":"Un format de comité de direction : des faits, des priorités, des décisions. Pas un rapport de 200 pages"},{"prestation":{"accroche":"Accompagnement de la mise en œuvre","texte":", si vous le souhaitez : plan de préventif, structuration de la GMAO, renégociation des prestations, montée en compétence"},"benefice":"Le même référent du cadrage à l''exécution. Les résultats se mesurent sur vos propres indicateurs"}]},{"type":"deroule","etapes":[{"titre":"Votre appel ou votre questionnaire.","texte":"Nous vous rappelons dans l''heure. Vingt minutes suffisent souvent à cerner le besoin."},{"titre":"Le diagnostic gratuit.","texte":"Premier état des lieux, sans contrepartie attendue, avec une recommandation écrite."},{"titre":"Le cadrage.","texte":"Un échange avec votre direction fixe l''objectif : économies, fiabilité, préparation d''un investissement, refonte de la fonction maintenance. Périmètre et sites posés par écrit."},{"titre":"L''audit terrain.","texte":"Visite des installations, entretiens, revue des historiques, de la GMAO, des contrats et des stocks."},{"titre":"L''analyse.","texte":"Les constats sont classés par enjeu : sécurité et conformité d''abord, disponibilité des équipements critiques ensuite, coûts enfin."},{"titre":"La restitution.","texte":"Rapport clair, présenté de vive voix à votre direction, avec un plan d''actions priorisé par gains attendus."},{"titre":"La mise en œuvre, si vous le voulez.","texte":"Exécution accompagnée, points d''avancement réguliers, résultats mesurés sur vos indicateurs."}]},{"type":"garanties","puces":[{"accroche":"Un rappel dans l''heure","texte":"du lundi au vendredi, 8h00 à 18h30, au 04 78 33 72 05, et un diagnostic initial gratuit, sans contrepartie attendue."},{"accroche":"Le même référent du cadrage à la restitution","texte":", évalué comme chaque collaborateur Migen en entretien technique et comportemental : 10 % des candidats retenus."},{"accroche":"La confidentialité par défaut","texte":"vos données, vos chiffres et vos pratiques restent entre nous. Un accord de confidentialité se signe dès le premier échange si vous le souhaitez."},{"accroche":"Un intervenant en règle avant d''entrer dans vos ateliers","texte":"habilitations à jour et vérifiables, démarche MASE pour la sécurité des interventions, évaluation EcoVadis pour la performance RSE. Les attestations sont transmises avec chaque plan de prévention, avant la visite."}]},{"type":"cta","question":"Besoin de savoir si votre budget maintenance est bien employé ?","bouton":"Demander mon diagnostic gratuit","href":"/contact/","rappel":"04 78 33 72 05, rappel dans l''heure"}]'::jsonb) where path = '/offres/audit-conseil-maintenance/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"[Étude de cas JOINT LYONNAIS : défaillances machines](/preuves/joint-lyonnais/) · Lyon, depuis février 2024. Diagnostic sur site puis plusieurs solutions chiffrées, arbitrées par le client selon son budget de PME, sans rachat de matériel neuf."},{"titre":"[Étude de cas ERIKS](/preuves/eriks/) · Un responsable maintenance en renfort pour piloter les équipes pendant une transition interne."},{"titre":"[Étude de cas VEEPEE : sites de Lyon](/preuves/veepee-sites-lyon/) · Six techniciens polyvalents et un contrat de préventif annuel sur les sites lyonnais."},{"titre":"[Étude de cas STELLANTIS : fonderie de Sept-Fons](/preuves/stellantis-fonderie-sept-fons/) · Préventif et curatif 7 jours sur 7 sur la fonderie et l''usinage."},{"titre":"[Étude de cas DANONE : lignes de production](/preuves/danone-lignes-de-production/) · Deux techniciens en 3x8 sur les lignes liquides et le conditionnement poudre, site de Steenvoorde."}]},{"type":"objections","questions":[{"question":"Combien coûte une prestation de conseil en maintenance industrielle ?","reponse":"Le diagnostic initial est gratuit. Au-delà, le prix dépend du périmètre, du nombre de sites et de la profondeur d''analyse : chaque demande fait l''objet d''un devis établi après le cadrage, ligne par ligne, hypothèses retenues comprises."},{"question":"Que se passe-t-il après la restitution ?","reponse":"Vous décidez. Certains clients exécutent le plan en interne, d''autres nous confient tout ou partie de la mise en œuvre, en prestation ponctuelle, en [sous-traitance de maintenance](/offres/residence/) avec un technicien intégré sur site, ou via l''abonnement Zéro arrêt. Aucune de ces suites n''est obligatoire : le rapport vous appartient."},{"question":"Faut-il une GMAO pour lancer la démarche ?","reponse":"Non. L''absence d''outil ou des historiques incomplets sont des constats utiles en soi. Nous travaillons alors à partir de vos factures, de vos plannings et des entretiens terrain, et la structuration des données entre dans les recommandations."},{"question":"Qui audite mon site ?","reponse":"Un référent technique salarié, ingénieur ou technicien de terrain, évalué en entretien technique et comportemental à l''entrée : 10 % des candidats retenus. Pas un consultant de passage qui n''a jamais ouvert une armoire électrique."},{"question":"En quoi êtes-vous différents d''un grand cabinet ?","reponse":"Un cabinet vend une méthodologie et repart après la restitution. Nous pouvons rester pour exécuter, et cette perspective discipline chaque recommandation : nous n''écrivons que ce que nous saurions faire nous-mêmes."},{"question":"Intervenez-vous partout en France ?","reponse":"Oui. Notre siège est à Lyon, avec deux implantations à Limonest et Écully, et trois autres agences à Montréal, Dubaï et Madrid. Nos techniciens sont rattachés à dix hubs, Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon et Nantes, et ils sont mobiles : un site hors de ces villes est audité comme les autres, le déplacement est simplement posé dans le cadrage."},{"question":"Vos intervenants peuvent-ils circuler dans nos ateliers en sécurité ?","reponse":"Oui. Le référent qui visite vos installations est salarié Migen, avec des habilitations à jour et vérifiables. Notre démarche MASE encadre la sécurité des interventions et notre évaluation EcoVadis mesure la performance RSE : les attestations vous sont transmises avec le plan de prévention, avant la première visite. Vos propres règles de site, accueil sécurité, permis de feu, consignations, s''appliquent sans exception."},{"question":"Faut-il s''engager sur une durée ?","reponse":"Non. Le diagnostic initial est gratuit et l''audit se contractualise sur un périmètre défini, avec une date de restitution. Ce qui vient après, exécution interne, mission ponctuelle, technicien intégré sur site ou abonnement Zéro arrêt, se décide une fois le rapport en main, et se contractualise séparément."},{"question":"Nous avons déjà un prestataire de maintenance. Cela pose-t-il un problème ?","reponse":"Non, et c''est souvent le point de départ. L''audit passe en revue les contrats en cours, leur adéquation au besoin réel et ce qu''ils couvrent vraiment. La conclusion peut être de les conserver, de les renégocier ou de les remettre en concurrence. Nous vous disons dans le rapport quand nous sommes nous-mêmes candidats à une ligne du plan d''actions."}]},{"type":"ctaFinal","question":"Besoin d''un regard extérieur avant de reconduire vos contrats ?","bouton":"Demander mon diagnostic gratuit","href":"/contact/","rappel":"04 78 33 72 05"}]'::jsonb) where path = '/offres/audit-conseil-maintenance/';
